+/** Selects a supported language from an Accept-Language header or uses the fallback. */
+export function selectLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  let best = fallback;
+  let bestQuality = 0;
+  for (const entry of header.split(",")) {
+    const parts = entry.trim().split(";");
+    const tag = parts.shift().trim().toLowerCase();
+    if (!/^(en|ko)(?:-[a-z0-9]{1,8})*$/.test(tag)) continue;
+    let quality = 1;
+    if (parts.length) {
+      if (parts.length !== 1) continue;
+      const match = parts[0].trim().match(/^q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/i);
+      if (!match) continue;
+      quality = Number(match[1]);
+    }
+    if (quality > bestQuality) {
+      best = tag.split("-")[0];
+      bestQuality = quality;
+    }
+  }
+  return best;
+}
